package com.crm.fees.service;
import com.crm.fees.entity.Fee;import com.crm.fees.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;
@Service @Transactional(readOnly=true) public class FeeBillingCandidates {private final FeeRepository fees;private final FeeTimeRepository times;private final FeeOfferingRepository offerings;public FeeBillingCandidates(FeeRepository f,FeeTimeRepository t,FeeOfferingRepository o){fees=f;times=t;offerings=o;}
 public record Candidate(String id,String customerId,String currency,String serviceName,String sourceTimeId,String hours,String rate,String amount,boolean immutable){}
 public Page<Candidate> list(String customer,String currency,int page){FeeAuthorization.admin();id(customer);if(currency==null||!currency.matches("[A-Z]{3}")||page<0)throw new IllegalArgumentException("Invalid billing candidate filters");return fees.findAll((root,q,c)->c.and(c.isNotNull(root.get("sourceTimeId")),c.equal(root.get("customerId"),customer),c.equal(root.get("currency"),currency),c.isNull(root.get("invoiceStatus")),c.isNull(root.get("paymentStatus"))),PageRequest.of(page,20,Sort.by("id"))).map(this::candidate);}
 public Candidate get(long id){FeeAuthorization.admin();return candidate(fees.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND)));}
 private Candidate candidate(Fee f){if(f.getSourceTimeId()==null||f.getExactHours()==null||f.getCurrency()==null||!f.getCurrency().matches("[A-Z]{3}")||f.getInvoiceStatus()!=null||f.getPaymentStatus()!=null)throw FeeFinance.conflict();id(f.getCustomerId());var time=times.findById(f.getSourceTimeId()).orElseThrow(FeeFinance::conflict);var offering=offerings.findById(time.getOfferingId()).orElseThrow(FeeFinance::conflict);if(time.isCancelled()||!f.getId().equals(time.getFeeId())||!java.util.Objects.equals(offering.getCustomerId(),f.getCustomerId())||!offering.getCurrency().equals(f.getCurrency())||f.getAmount().compareTo(time.getAmount())!=0||f.getHourlyRate().compareTo(time.getAppliedRate())!=0||f.getExactHours().compareTo(time.getHours())!=0||FeeFinance.amount(f.getHourlyRate(),f.getExactHours()).compareTo(f.getAmount())!=0)throw FeeFinance.conflict();return new Candidate(f.getId().toString(),f.getCustomerId(),f.getCurrency(),f.getServiceName(),f.getSourceTimeId().toString(),f.getExactHours().toPlainString(),f.getHourlyRate().toPlainString(),f.getAmount().toPlainString(),true);}
 private void id(String id){if(id==null||!id.matches("[1-9][0-9]{0,18}"))throw new IllegalArgumentException("Canonical customer required");try{Long.parseLong(id);}catch(NumberFormatException e){throw new IllegalArgumentException("Invalid customer");}}
}
